import { describe, expect, it } from 'vitest';
import type { Course, Hole, ObstacleDescriptor, SurfaceDescriptor } from '../src/courses/types';

const courseModules = import.meta.glob('../src/courses/data/*.ts', {
  eager: true,
  import: 'default',
}) as Record<string, Course>;

const courses = Object.entries(courseModules)
  .map(([path, course]) => ({ path, course }))
  .sort((a, b) => a.path.localeCompare(b.path));

const SUPPORTED_OBSTACLE_TYPES = new Set<ObstacleDescriptor['type']>([
  'wall', 'bumper', 'pillar', 'block',
  'spinner', 'windmill', 'gate', 'platform',
  'water', 'void', 'reset-zone',
]);
const SUPPORTED_SURFACE_SHAPES = new Set<SurfaceDescriptor['shape']>(['box', 'ramp', 'cylinder', 'mesh']);
const MAX_SHOTS_PER_HOLE = 12;

const finite = (value: number, label: string): void => {
  expect(Number.isFinite(value), `${label} must be a finite number, got ${String(value)}`).toBe(true);
};

const positive = (value: number, label: string): void => {
  finite(value, label);
  expect(value, `${label} must be > 0`).toBeGreaterThan(0);
};

const vec3 = (value: { x: number; y: number; z: number }, label: string): void => {
  finite(value.x, `${label}.x`);
  finite(value.y, `${label}.y`);
  finite(value.z, `${label}.z`);
};

function validateHole(course: Course, hole: Hole): void {
  const label = `${course.id}/${hole.id}`;

  expect(hole.id.trim(), `${label}: hole id must not be empty`).not.toBe('');
  expect(hole.name.trim(), `${label}: hole name must not be empty`).not.toBe('');
  expect(Number.isInteger(hole.par), `${label}: par must be an integer`).toBe(true);
  expect(hole.par, `${label}: par must be at least 1`).toBeGreaterThanOrEqual(1);
  expect(hole.par, `${label}: par must be below maxShots (${MAX_SHOTS_PER_HOLE})`).toBeLessThan(MAX_SHOTS_PER_HOLE);

  vec3(hole.spawn, `${label}: spawn`);
  vec3(hole.cup.position, `${label}: cup.position`);
  positive(hole.cup.radius, `${label}: cup.radius`);
  positive(hole.cup.captureDepth, `${label}: cup.captureDepth`);
  vec3(hole.bounds.min, `${label}: bounds.min`);
  vec3(hole.bounds.max, `${label}: bounds.max`);

  for (const axis of ['x', 'y', 'z'] as const) {
    expect(
      hole.bounds.min[axis],
      `${label}: bounds.min.${axis} must be <= bounds.max.${axis}`,
    ).toBeLessThanOrEqual(hole.bounds.max[axis]);
    expect(
      hole.spawn[axis],
      `${label}: spawn.${axis} must be inside bounds`,
    ).toBeGreaterThanOrEqual(hole.bounds.min[axis]);
    expect(hole.spawn[axis], `${label}: spawn.${axis} must be inside bounds`).toBeLessThanOrEqual(hole.bounds.max[axis]);
    expect(
      hole.cup.position[axis],
      `${label}: cup.position.${axis} must be inside bounds`,
    ).toBeGreaterThanOrEqual(hole.bounds.min[axis]);
    expect(
      hole.cup.position[axis],
      `${label}: cup.position.${axis} must be inside bounds`,
    ).toBeLessThanOrEqual(hole.bounds.max[axis]);
  }

  expect(hole.surfaces.length, `${label}: must contain at least one surface`).toBeGreaterThan(0);

  const elementIds = new Set<string>();
  for (const surface of hole.surfaces) {
    expect(surface.id.trim(), `${label}: surface id must not be empty`).not.toBe('');
    expect(elementIds.has(surface.id), `${label}: duplicate element id "${surface.id}"`).toBe(false);
    elementIds.add(surface.id);
    expect(SUPPORTED_SURFACE_SHAPES.has(surface.shape), `${label}/${surface.id}: unsupported surface shape "${surface.shape}"`).toBe(true);
    vec3(surface.transform.position, `${label}/${surface.id}: transform.position`);
    vec3(surface.size, `${label}/${surface.id}: size`);
    positive(surface.size.x, `${label}/${surface.id}: size.x`);
    positive(surface.size.y, `${label}/${surface.id}: size.y`);
    positive(surface.size.z, `${label}/${surface.id}: size.z`);
  }

  for (const obstacle of hole.obstacles) {
    expect(obstacle.id.trim(), `${label}: obstacle id must not be empty`).not.toBe('');
    expect(elementIds.has(obstacle.id), `${label}: duplicate element id "${obstacle.id}"`).toBe(false);
    elementIds.add(obstacle.id);
    expect(
      SUPPORTED_OBSTACLE_TYPES.has(obstacle.type),
      `${label}/${obstacle.id}: unsupported obstacle type "${String(obstacle.type)}"`,
    ).toBe(true);
    vec3(obstacle.transform.position, `${label}/${obstacle.id}: transform.position`);
    vec3(obstacle.size, `${label}/${obstacle.id}: size`);
    positive(obstacle.size.x, `${label}/${obstacle.id}: size.x`);
    positive(obstacle.size.y, `${label}/${obstacle.id}: size.y`);
    positive(obstacle.size.z, `${label}/${obstacle.id}: size.z`);

    if ('motion' in obstacle) {
      vec3(obstacle.motion.axis, `${label}/${obstacle.id}: motion.axis`);
      finite(obstacle.motion.speed, `${label}/${obstacle.id}: motion.speed`);
      if (obstacle.motion.distance !== undefined) {
        positive(obstacle.motion.distance, `${label}/${obstacle.id}: motion.distance`);
      }
      if (obstacle.motion.phase !== undefined) {
        finite(obstacle.motion.phase, `${label}/${obstacle.id}: motion.phase`);
      }
    }
  }
}

describe('course data validation', () => {
  it('contains exactly 10 courses × 9 holes = 90 holes', () => {
    expect(courses.length, `Expected 10 course modules in src/courses/data, found ${courses.length}: ${courses.map(({ path }) => path).join(', ')}`).toBe(10);
    for (const { path, course } of courses) {
      expect(course.holes.length, `${path} (${course.id}) must contain exactly 9 holes`).toBe(9);
    }
    const totalHoles = courses.reduce((sum, { course }) => sum + course.holes.length, 0);
    expect(totalHoles, `Expected exactly 90 holes across all courses, found ${totalHoles}`).toBe(90);
  });

  it('uses globally unique course and hole identifiers', () => {
    const courseIds = new Set<string>();
    const holeIds = new Map<string, string>();

    for (const { path, course } of courses) {
      expect(course.id.trim(), `${path}: course id must not be empty`).not.toBe('');
      expect(courseIds.has(course.id), `${path}: duplicate course id "${course.id}"`).toBe(false);
      courseIds.add(course.id);

      for (const hole of course.holes) {
        const previousCourse = holeIds.get(hole.id);
        expect(
          previousCourse,
          `Duplicate hole id "${hole.id}" in courses "${previousCourse}" and "${course.id}"`,
        ).toBeUndefined();
        holeIds.set(hole.id, course.id);
      }
    }
  });

  it('has valid gameplay geometry, par/maxShots compatibility and supported obstacle types', () => {
    for (const { course } of courses) {
      for (const hole of course.holes) validateHole(course, hole);
    }
  });
});
